import React from 'react';
import { Link } from 'react-router-dom';

const Header = () => {
  return (
    <header style={{ background: '#333', color: 'white', padding: '1rem 0' }}>
      <div className="container">
        <nav style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h1>Amol Electricals</h1>
          <div>
            <Link to="/" style={{ color: 'white', margin: '0 15px', textDecoration: 'none' }}>Home</Link>
            <Link to="/services" style={{ color: 'white', margin: '0 15px', textDecoration: 'none' }}>Services</Link>
            <Link to="/book" style={{ color: 'white', margin: '0 15px', textDecoration: 'none' }}>Book Service</Link>
          </div>
        </nav>
      </div>
    </header>
  );
};

export default Header;
